[SubscribesTo(classStr(NDXBatchMultithreading), delegateStr(NDXBatchMultithreading, onRunControllerPre))]
public static void NDXBatchMultithreading_onRunControllerPre(
    NDXMultiThreadingCreateTaskController _controller, 
    NDXEventHandlerResultBatch _eventResult)
{
    NDXMultiThreadingCreateTaskContract contractCreateTask = _controller.getDataContractObject('_contract');
    if (!contractCreateTask)
    {
        throw Error(strFmt("@SYS23264", classStr(NDXMultiThreadingCreateTaskContract)));
    }
    NDXTotalNumberOfTasksNeeded numberOfThreads = NDXUmsatzParametersGlobal::find().TotalNumberOfTasksNeeded;
    if (!numberOfThreads)
    {
        numberOfThreads = 5;
    }
    contractCreateTask.parmNumberOfThreads(numberOfThreads);
    _eventResult.parmUmsBasisLJ(contractCreateTask.parmUmsBasisLJ());
    _eventResult.parmSignatureUmsVJ(contractCreateTask.parmSignatureUmsVJ());

